'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { LRUCache } = require('./src/lru');

test('capacity requires a positive integer Number', () => {
  for (const capacity of [0, -0, -1, 0.5, 1.5, Infinity, -Infinity, NaN, '2', undefined, null, true, 2n, Symbol(), {}, new Number(2)]) {
    assert.throws(() => new LRUCache(capacity), RangeError);
  }
  assert.throws(() => new LRUCache(), RangeError);
  for (const capacity of [1, 2, Number.MAX_SAFE_INTEGER, Number.MAX_VALUE]) {
    assert.equal(new LRUCache(capacity).size, 0);
  }
});

test('undefined values refresh recency; has and misses do not', () => {
  const cache = new LRUCache(2);
  cache.set('a', undefined).set('b', 2);
  assert.equal(cache.get('a'), undefined);
  cache.set('c', 3);
  assert.equal(cache.has('a'), true);
  assert.equal(cache.has('b'), false);
  assert.equal(cache.has('c'), true);
  assert.equal(cache.get('missing'), undefined);
  cache.set('d', 4);
  assert.equal(cache.has('a'), false);
  assert.equal(cache.has('c'), true);
  assert.equal(cache.has('d'), true);
});

test('updates preserve size and refresh recency', () => {
  const cache = new LRUCache(2);
  cache.set('a', 1).set('b', 2);
  assert.equal(cache.set('a', 3), cache);
  assert.equal(cache.size, 2);
  assert.equal(cache.has('b'), true);
  cache.set('c', 4);
  assert.equal(cache.has('b'), false);
  assert.equal(cache.get('a'), 3);
  assert.equal(cache.get('c'), 4);
  const single = new LRUCache(1);
  single.set('a', 1).set('a', undefined);
  assert.equal(single.size, 1);
  assert.equal(single.has('a'), true);
  single.set('b', 2);
  assert.equal(single.has('a'), false);
  assert.equal(single.size, 1);
});

test('arbitrary keys and values follow Map semantics', () => {
  const object = {};
  const otherObject = {};
  const symbol = Symbol();
  const fn = () => {};
  const entries = [[object, otherObject], [otherObject, object], [symbol, fn], [fn, symbol], [NaN, null], [-0, false], [undefined, undefined], [null, 1n], [1n, NaN], ['1', 0], [1, 'number']];
  const cache = new LRUCache(entries.length);
  for (const [key, value] of entries) cache.set(key, value);
  assert.equal(cache.size, entries.length);
  for (const [key, value] of entries) {
    assert.equal(cache.has(key), true);
    assert.equal(cache.get(key), value);
  }
  assert.equal(cache.has({}), false);
  assert.equal(cache.has(Symbol()), false);
  assert.equal(cache.get(+0), false);
  cache.set(+0, true).set(Number('not a number'), 'nan');
  assert.equal(cache.size, entries.length);
  assert.equal(cache.get(-0), true);
  assert.equal(cache.get(NaN), 'nan');
});

test('deletion preserves surviving recency and caches are independent', () => {
  const cache = new LRUCache(3);
  const other = new LRUCache(1);
  cache.set('a', 1).set('b', 2).set('c', 3);
  other.set('a', 9);
  assert.equal(cache.delete('b'), true);
  assert.equal(cache.delete('b'), false);
  assert.equal(cache.size, 2);
  cache.set('d', 4).set('e', 5);
  assert.equal(cache.has('a'), false);
  assert.equal(cache.get('c'), 3);
  assert.equal(cache.get('d'), 4);
  assert.equal(cache.get('e'), 5);
  assert.equal(other.get('a'), 9);
  assert.equal(other.size, 1);
});

